fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let mut result = Vec::with_capacity(a.len()); // Create a new vector with the same capacity as the input vector

    let mut idx = 0; // Initialize the loop counter
    let len = a.len(); // Get the length of the input vector

    while idx < len { // Loop until the counter reaches the length of the input vector
        result.push(1); // Push the value 1 into the result vector
        idx += 1; // Increment the loop counter
    }

    result // Return the constructed vector
}